import json,statistics,hashlib,platform,subprocess
from pathlib import Path
lab=Path(__file__).resolve().parent
raw=json.loads((lab/'comparison-final.json').read_text());rows=raw['samples'];assert len(rows)==60
result=dict(scope=raw['scope'],receipts=raw['receipts'],samples=rows,summary=[],environment=dict(platform=platform.platform(),cpu=subprocess.check_output(['lscpu'],text=True)))
for subject in ['compiler','cli']:
 for lane in [['a','b','c'],['d','e']]:
  assert len({r['wasm_sha256'] for r in rows if r['subject']==subject and r['config'] in lane})==1
 for temperature in ['cold','warm']:
  for config in ['a','b','c','d','e']:
   group=[r for r in rows if (r['subject'],r['temperature'],r['config'])==(subject,temperature,config)]
   assert len(group)==3 and all(r['exit']==0 for r in group)
   summary=dict(subject=subject,temperature=temperature,config=config)
   for key in ['wall_s','peak_process_tree_rss_sum_bytes','process_tree_user_cpu_s','process_tree_system_cpu_s']:
    values=[r[key] for r in group];summary[key]=dict(median=statistics.median(values),min=min(values),max=max(values))
   if config in ['a','b']:
    for key in ['prepare_ms','worker_ms','finalize_ms','total_ms']:
     summary[key]=statistics.median(r['phases'][key] for r in group)
    summary['waves']=len(group[0]['phases']['waves'])
    summary['modules']=group[0]['phases']['modules']
    summary['wave_job_counts']=[x['jobs'] for x in group[0]['phases']['waves']]
    summary['wave_wall_ms_medians']=[statistics.median(r['phases']['waves'][i]['wall_ms'] for r in group) for i in range(summary['waves'])]
   result['summary'].append(summary)
