import @vibe/compiler/cache { ast_binary_reader_new }
import @vibe/lowering_worker {
  PreludeSharedContext, read_prelude_shared_context, read_prelude_shared_job, read_prelude_module_product
}
fn use_job(ctx: PreludeSharedContext) -> Unit with Exception {
  let _ = read_prelude_shared_job(reader = ast_binary_reader_new(Bytes::new()), context = ctx, digest = "")
  ()
}
fn main() -> Unit allows Exception {
  let context = handle { Some(read_prelude_shared_context(reader = ast_binary_reader_new(Bytes::new()))) } with { Exception::Throw(_) => None }
  match context { Some(ctx) => use_job(ctx), None => () }
  let result = handle { let _ = read_prelude_module_product(reader = ast_binary_reader_new(Bytes::new())); "accepted" } with { Exception::Throw(msg) => msg }
  assert(result != "accepted")
}
